from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize one scalar exactly as scoring does, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length using binary search over C-level string slices."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every row using its row-specific source-column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by deterministic length-weighted repeated-value mass."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            repeated = sum(
                count * (count - 1)
                for count in counts.values()
            )
            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )

            if mode == 0:
                score = weighted
            else:
                score = weighted + repeated * max(
                    1, total_length // max(1, n)
                )

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    @staticmethod
    def _group_rank(cells, rows, columns) -> List[int]:
        """Rank remaining columns by exact-value repetition within one row group."""
        ranked = []

        for column in columns:
            counts = {}
            for row in rows:
                value = cells[row, column]
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _prefix_orders(self, cells) -> List[List[int]]:
        """Recursively route groups by 1-, 2-, or 4-character field prefixes."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        result = [None] * n
        max_depth = 3
        min_branch = 3
        width_choices = (1, 2, 4)

        def finish(rows, remaining, prefix):
            """Assign a deterministic repetition-ranked suffix to a terminal group."""
            suffix = self._group_rank(cells, rows, remaining)
            order = prefix + suffix
            for row in rows:
                result[row] = order[:]

        def visit(rows, remaining, prefix, depth):
            """Choose one high-value prefix partition and recurse into its buckets."""
            if len(remaining) <= 1 or len(rows) < min_branch or depth >= max_depth:
                finish(rows, remaining, prefix)
                return

            # Limit inspected fields while retaining deterministic tie behavior.
            ranked_fields = self._group_rank(cells, rows, remaining)
            inspect = ranked_fields[:16]

            best = None
            for column in inspect:
                for width in width_choices:
                    buckets = {}
                    for row in rows:
                        key = cells[row, column][:width]
                        buckets.setdefault(key, []).append(row)

                    if len(buckets) <= 1:
                        continue

                    # Prefix collision mass models reusable character edges.
                    score = sum(
                        min(width, len(key)) * len(bucket) * (len(bucket) - 1)
                        for key, bucket in buckets.items()
                    )

                    # Prefer more useful branching after the primary score.
                    choice = (score, len(buckets), -column, -width)
                    if best is None or choice > best[0]:
                        best = (choice, column, buckets)

            if best is None or best[0][0] <= 0:
                finish(rows, remaining, prefix)
                return

            _, lead, buckets = best
            next_remaining = [column for column in remaining if column != lead]
            next_prefix = prefix + [lead]

            # Stable key ordering makes the construction deterministic.
            for key in sorted(buckets, key=lambda value: (value,)):
                bucket_rows = buckets[key]
                visit(bucket_rows, next_remaining, next_prefix, depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)
        return result

    def _candidate(self, cells, orders):
        """Serialize and exactly score one candidate, then sort rows lexicographically."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row)
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best of two global orders and one prefix-routed order losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        prefix_orders = self._prefix_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            prefix_orders,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders
